const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const latitude = 34.498828;
  const longitude = -112.246886;
  const point = ee.Geometry.Point(longitude, latitude);
  const radiusMiles = 50;
  const radiusMeters = radiusMiles * 1609.34; // Convert miles to meters
  const geometry = point.buffer(radiusMeters);

  const startDate = '2017-06-20';
  const endDate = '2017-06-30';

  // 2. Data Acquisition & Check
  const viirsCollection = ee.ImageCollection('FIRMS/VIIRS/VNP14IMGTDL_NRT')
    .filterDate(startDate, endDate)
    .filterBounds(geometry);

  const collectionSize = await viirsCollection.size().getInfo();

  if (collectionSize === 0) {
    console.log(`No VIIRS images found for the specified period (${startDate} to ${endDate}) and location.`);
    console.log("C1");
    return;
  }
  console.log(`VIIRS images in initial collection: ${collectionSize}`);

  // 3. Processing - Filter for active fires
  // VIIRS NRT documentation suggests confidence > 30 for active fires.
  // The 'confidence' band is an integer representing confidence (0-100).
  const fireDetections = viirsCollection.filter(ee.Filter.gt('confidence', 30));

  const fireCount = await fireDetections.size().getInfo();

  // 4. Calculation - Check for existence of fire pixels
  // If fireCount is 0, it means no active fires were detected with sufficient confidence.
  if (fireCount === 0) {
    console.log(`No active fires (confidence > 30) detected within the ${radiusMiles}-mile radius.`);
    console.log("B"); // No fires visible
  } else {
    // To provide some evidence, let's get the number of fire pixels detected in the region
    // We'll mosaic the fire detections and count pixels within the geometry.
    // The 'fire_type' band can be used for counting individual fire pixels.
    const fireImage = fireDetections.select('fire_type').mosaic();

    const firePixelCount = await fireImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: geometry,
      scale: 375, // VIIRS pixel resolution
      maxPixels: 1e9,
      crs: 'EPSG:4326' // Specify CRS for consistency
    }).get('fire_type').getInfo();

    if (firePixelCount === null) {
      console.log("Failed to count fire pixels.");
      console.log("C3");
      return;
    }

    console.log(`Total active fire images detected: ${fireCount}`);
    console.log(`Total fire pixels (confidence > 30) in the region: ${firePixelCount}`);

    if (firePixelCount > 0) {
      console.log("A"); // Yes, fires were visible
    } else {
      console.log("B"); // No valid fire pixels detected after reduceRegion (e.g., if fire_type band was all nulls within the filter)
    }
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
